const body = $json.body ?? $json ?? {};
const calendar = body.calendar ?? {};
const task = body.task ?? {};

const missing = [];
if (body.eventType !== 'task.calendar_request') missing.push('eventType');
if (!body.requestId) missing.push('requestId');
if (!calendar.title) missing.push('calendar.title');
if (!calendar.date) missing.push('calendar.date');
if (!calendar.endDate) missing.push('calendar.endDate');

const datePattern = /^\d{4}-\d{2}-\d{2}$/;
const invalid = [];
if (calendar.date && !datePattern.test(calendar.date)) invalid.push('calendar.date must be YYYY-MM-DD');
if (calendar.endDate && !datePattern.test(calendar.endDate)) invalid.push('calendar.endDate must be YYYY-MM-DD');
if (datePattern.test(calendar.date ?? '') && datePattern.test(calendar.endDate ?? '') && calendar.endDate <= calendar.date) {
  invalid.push('calendar.endDate must be after calendar.date for all-day Google events');
}

if (missing.length || invalid.length) {
  const details = [...missing.map((field) => `missing ${field}`), ...invalid].join(', ');
  throw new Error(`Invalid AI Project Hub payload: ${details}`);
}

return [{
  json: {
    requestId: body.requestId,
    source: body.source ?? 'ai-project-hub',
    user: body.user ?? null,
    task,
    project: body.project ?? null,
    calendar: {
      title: String(calendar.title).trim(),
      date: calendar.date,
      endDate: calendar.endDate,
      allDay: calendar.allDay !== false,
      timezone: calendar.timezone ?? 'Europe/Oslo',
      description: calendar.description ?? ''
    }
  }
}];
